// A native <select> whose options carry what a person decides with — a time, a price, a department, a badge, a typeface —
// instead of one line of text. It is the browser's own control (`appearance: base-select`), so the keyboard, type-to-jump,
// the form value, `required` and the role stay where they belong, and a browser without customizable select draws an
// ordinary select whose option text still reads as a sentence.
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createEffect, createUniqueId, For, Show } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

export interface PickerOption {
  readonly value: string;
  /** The name column. It is also the whole option in a browser without customizable select, so it has to stand alone. */
  readonly label: string;
  /** The fact the choice turns on: a time, a price, a title and department. */
  readonly detail?: string | undefined;
  /** A third column, for what needs saying: "needs approval", a currency, a weight. */
  readonly note?: string | undefined;
  /** An inline style for the label alone: the font-preview case, where the option is set in its own typeface. */
  readonly style?: Readonly<Record<string, string>> | undefined;
  readonly disabled?: boolean | undefined;
}

export interface PickerProps {
  /** The field's name, which is also the select's accessible name. */
  readonly label: string;
  /** The form field's name, when the select is in a form. */
  readonly name?: string | undefined;
  readonly options: ReadonlyArray<PickerOption>;
  /** Controlled: the chosen value. Leave it out and the select owns it. */
  readonly value?: string | undefined;
  readonly onValueChange?: ((value: string) => void) | undefined;
  /** The option grid's columns (default `1fr auto auto`): wide enough for the widest detail and note in the list. */
  readonly columns?: string | undefined;
  readonly class?: string | undefined;
}

/** True where the browser draws a customizable select: the rich layout is only worth having where it is understood. */
const CUSTOM = "(appearance: base-select)";
/** And only with a precise pointer: a touch device keeps the operating system's own picker, which is the better control. */
const FINE = "(hover: hover) and (pointer: fine)";

const rootClass = css.cn(css.display("grid"), css.gap(t.space._2), css.width("100%"));

const labelClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.fontWeight("500"),
  css.color(t.color.text),
);

// The closed control. `appearance: auto` is the native select everywhere; the rich half is the two conditions below, so a
// browser without either keeps the platform's control and the option text alone.
const selectClass = css.cn(
  css.appearance("auto"),
  css.width("100%"),
  css.font("inherit"),
  css.color(t.color.text),
  css.media(FINE)(
    css.supports(CUSTOM)(
      css.appearance("base-select"),
      css.boxSizing("border-box"),
      css.bg(t.color.surface),
      css.border("1px solid", t.color.border),
      css.borderRadius(t.radius.md),
      css.padding("0", t.space._3),
      css.cursor("pointer"),
      css.fontSize(t.font.size),
      css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
      // the arrow is the UA's ::picker-icon; it takes the muted colour and turns over when the list is open
      css.pickerIcon(css.color(t.color.muted), css.transition("rotate 120ms")),
      css.open(css.pickerIcon(css.rotate("180deg"))),
      // the list itself: the UA places it; the skin paints it
      css.picker(
        css.bg(t.color.surface),
        css.border("1px solid", t.color.border),
        css.borderRadius(t.radius.md),
        css.padding(t.space._1),
        css.boxShadow("0 8px 24px rgb(0 0 0 / 0.18)"),
      ),
    ),
  ),
);

// The button the browser puts inside the control ("selectedcontent"), so the closed form shows the same row the list does.
const buttonClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.gap(t.space._2),
  css.width("100%"),
  css.padding(t.space._2, "0"),
  css.bg("transparent"),
  css.border("none"),
  css.color("inherit"),
  css.font("inherit"),
  css.textAlign("start"),
  css.cursor("pointer"),
);

// One option: the article's grid — a name that takes what is left, then the facts in columns, so a comparison is a glance
// down one column and not a sentence to hold in the head.
const optionClass = css.cn(
  css.display("grid"),
  css.gridTemplateColumns("var(--picker-columns, 1fr auto auto)"),
  css.alignItems("center"),
  css.gap(t.space._3),
  css.padding(t.space._2),
  css.borderRadius(t.radius.sm),
  css.checked(css.fontWeight("600")),
  css.attr("aria-disabled", "true")(css.color(t.color.textDisabled)),
);

const nameClass = css.cn(css.color(t.color.text), css.overflowWrap("anywhere"));

const detailClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.whiteSpace("nowrap"),
);

// A note is a badge, and only the options that carry one: the list says which choices need attention before the value moves.
const noteClass = css.cn(
  css.justifySelf("end"),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.fontVariantNumeric("tabular-nums"),
  css.whiteSpace("nowrap"),
);

const badgeClass = css.cn(
  css.padding("0.125rem", t.space._2),
  css.borderRadius("999px"),
  css.bg(t.color.buttonBackground),
  css.color(t.color.text),
);

// Between the columns in the plain control: a comma keeps the option a sentence where the spans are flattened to text, and
// the rich layout hides it.
const separatorClass = css.cn(css.supports(CUSTOM)(css.display("none")));

/**
 * A native `<select>` with rich options.
 *
 * `appearance: base-select` makes the options part of the page, so each one can hold a grid: the name, the fact it turns on
 * and a note. The control is still the platform's — arrows, type-to-jump, Escape, the form value and the accessible name are
 * the browser's — and where the platform does not draw a customizable select (or the pointer is coarse) the same markup is
 * an ordinary select whose options are their text, which is why the separator spans exist.
 */
export const Picker = (props: PickerProps): JSX.Element => {
  const id = createUniqueId();
  // A controlled value is written to the control after its options exist: a `value` bound while the list is still being
  // built lands on an empty select and is dropped (Chrome resets it to no selection), so the write is an effect and the
  // uncontrolled case never writes at all (the browser starts on the first option).
  let element: HTMLSelectElement | undefined;
  createEffect(
    () => props.value,
    (next) => {
      if (next !== undefined && element !== undefined && element.value !== next) {
        element.value = next;
      }
    },
  );

  return (
    <div data-part="picker" class={css.cn(rootClass, props.class)}>
      <label class={labelClass} for={id}>
        {props.label}
      </label>
      <select
        id={id}
        name={props.name}
        ref={(select) => {
          element = select;
        }}
        class={selectClass}
        style={{ "--picker-columns": props.columns ?? "1fr auto auto" }}
        onChange={(event) => props.onValueChange?.(event.currentTarget.value)}
      >
        <button type="button" class={buttonClass}>
          <selectedcontent />
        </button>
        <For each={props.options}>
          {(option) => (
            <option value={option.value} disabled={option.disabled} class={optionClass}>
              <span class={nameClass} style={option.style}>
                {option.label}
              </span>
              <Show when={option.detail}>
                {(detail) => (
                  <>
                    <span class={separatorClass} aria-hidden="true">
                      ,{" "}
                    </span>
                    <span class={detailClass}>{detail()}</span>
                  </>
                )}
              </Show>
              <Show when={option.note}>
                {(note) => (
                  <>
                    <span class={separatorClass} aria-hidden="true">
                      ,{" "}
                    </span>
                    <span class={`${badgeClass} ${noteClass}`}>{note()}</span>
                  </>
                )}
              </Show>
            </option>
          )}
        </For>
      </select>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

// The picker is the browser's own select with rich options, so what is worth checking is what the platform does with it:
// the options still read as a sentence when the rich layout is not drawn, the grid is what makes a comparison a glance, and
// the value and the closed control are the select's.
import { render } from "@solidjs/web";
import { afterEach, describe, expect, it } from "vite-plus/test";

import { Picker, type PickerOption } from "./picker.tsx";

const OPTIONS: ReadonlyArray<PickerOption> = [
  { value: "same-day", label: "Same-day courier", detail: "Today by 9 pm", note: "$14.00" },
  { value: "express", label: "Express", detail: "Tomorrow", note: "$8.50" },
  { value: "pickup", label: "Pickup point", detail: "2–3 days", note: "Free", disabled: true },
];

const mounted: Array<() => void> = [];

afterEach(() => {
  for (const dispose of mounted.splice(0)) {
    dispose();
  }
});

const mount = (
  props: { readonly value?: string; readonly onValueChange?: (v: string) => void } = {},
) => {
  const host = document.createElement("div");
  document.body.append(host);
  const dispose = render(
    () => (
      <Picker
        label="Delivery"
        name="delivery"
        options={OPTIONS}
        columns="1fr 7rem 4.5rem"
        {...props}
      />
    ),
    host,
  );
  mounted.push(() => {
    dispose();
    host.remove();
  });
  return host;
};

const part = <T extends Element>(host: ParentNode, selector: string): T => {
  const element = host.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`picker: no ${selector}`);
  }
  return element;
};

/** Whether this browser draws a customizable select at all (Chrome 135 and Safari 27 do; Firefox does not yet). */
const rich = (): boolean =>
  CSS.supports("appearance", "base-select") && CSS.supports("selector(::picker(select))");

describe("Picker", () => {
  it("is a labelled select with a button and one option per value", () => {
    const host = mount();
    const field = part<HTMLElement>(host, '[data-part="picker"]');
    const label = part<HTMLLabelElement>(field, "label");
    const select = part<HTMLSelectElement>(field, "select");

    expect(label.textContent).toBe("Delivery");
    expect(label.getAttribute("for")).toBe(select.id);
    expect(select.name).toBe("delivery");
    // the platform's control, with the browser's own button and mirror inside it
    expect(select.querySelector("button")).not.toBeNull();
    expect(select.querySelector("selectedcontent")).not.toBeNull();
    expect([...select.options].map((option) => option.value)).toEqual([
      "same-day",
      "express",
      "pickup",
    ]);
    expect(select.options[2]?.disabled).toBe(true);
  });

  it("keeps every option readable as a sentence, which is the whole of the plain control", () => {
    const host = mount();
    const select = part<HTMLSelectElement>(host, "select");
    const text = select.options[0]?.textContent?.replace(/\s+/g, " ").trim();
    // the name, the fact and the note survive as text — the rich layout is an addition, not the content
    expect(text).toContain("Same-day courier");
    expect(text).toContain("Today by 9 pm");
    expect(text).toContain("$14.00");
  });

  it("draws the rich layout where the browser has it: base-select and the option grid", () => {
    if (!rich()) {
      return;
    }
    const host = mount();
    const select = part<HTMLSelectElement>(host, "select");
    expect(getComputedStyle(select).appearance).toBe("base-select");

    const option = part<HTMLOptionElement>(host, "option");
    const grid = getComputedStyle(option);
    expect(grid.display).toBe("grid");
    // three columns: the name takes what is left, then the detail and the note
    expect(grid.gridTemplateColumns.split(" ").length).toBe(3);
  });

  it("reports the value the browser committed, and the mirror follows it", async () => {
    const seen: string[] = [];
    const host = mount({ onValueChange: (value) => seen.push(value) });
    const select = part<HTMLSelectElement>(host, "select");

    select.value = "express";
    select.dispatchEvent(new Event("change", { bubbles: true }));
    expect(seen).toEqual(["express"]);
    expect(select.value).toBe("express");

    if (rich()) {
      // the closed control shows the chosen row, which is what `selectedcontent` is for — on the frame after the commit
      await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
      const button = part<HTMLElement>(host, "select button");
      expect(button.textContent).toContain("Express");
      expect(button.textContent).toContain("Tomorrow");
    }
  });

  it("takes a controlled value from the host", () => {
    const host = mount({ value: "pickup" });
    expect(part<HTMLSelectElement>(host, "select").value).toBe("pickup");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
